INSERT INTO testimonials (author_name, author_role, city, quote, detail, rating, sort_order) VALUES
  ('Salma B.', 'student', 'Casablanca', 'J''étais à 8/20 en maths en 1ère Bac. Après 4 mois avec mon prof INCLASS, j''ai eu 15,5 au régional. Il m''explique jusqu''à ce que je comprenne vraiment.', 'Mathématiques · 2ème Bac SM', 5, 1),
  ('Youssef E.', 'parent', 'Rabat', 'Ce que j''apprécie, c''est le compte rendu après chaque séance. Je sais exactement ce que mon fils a travaillé et où il bloque encore.', 'Parent d''un élève de 6ème année', 5, 2),
  ('Nadia L.', 'tutor', 'Marrakech', 'En 6 mois sur INCLASS j''ai construit un planning de 18 heures par semaine. Les paiements arrivent à l''heure et je choisis mes élèves.', 'Professeure de physique-chimie', 5, 3),
  ('Imane K.', 'student', 'Tanger', 'Les cours en ligne le soir m''ont sauvée pendant la prépa. Zéro déplacement et un prof d''anglais qui m''a fait passer le TOEFL à 98.', 'Anglais · Préparation TOEFL', 5, 4),
  ('Karim Z.', 'parent', 'Agadir', 'Deux profs testés, le bon trouvé du premier coup pour ma fille. Le remplacement gratuit après le premier cours, ça change tout.', 'Parent d''une élève de 2ème Bac', 5, 5);
